import { mkdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import Database from 'better-sqlite3';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import * as schema from './schema.js';

export type Db = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

/** Migration SQL lives in `drizzle/` at the app root (generated by `pnpm db:generate`, shipped in the image). */
const MIGRATIONS_DIR = process.env.MIGRATIONS_DIR ?? resolve(process.cwd(), 'drizzle');

/** Opens a SQLite file (or ':memory:'), enables WAL + foreign keys, and applies migrations. */
export function openDb(file: string, migrationsFolder = MIGRATIONS_DIR): Db {
	const sqlite = new Database(file);
	sqlite.pragma('journal_mode = WAL');
	sqlite.pragma('foreign_keys = ON');
	const db = drizzle(sqlite, { schema });
	// Write transactions read, then write. A deferred BEGIN fails at once (SQLITE_BUSY_SNAPSHOT,
	// which busy_timeout cannot wait out) if another connection commits in between, so take
	// the write lock up front unless a caller asks otherwise.
	const transaction = db.transaction.bind(db);
	db.transaction = ((fn, config) =>
		transaction(fn, { behavior: 'immediate', ...config })) as typeof db.transaction;
	migrate(db, { migrationsFolder });
	return db;
}

export function dbPath(dataDir = process.env.DATA_DIR ?? './data'): string {
	return join(dataDir, 'hub.db');
}

let instance: Db | undefined;

/** Lazily opens the app database at `${DATA_DIR ?? './data'}/hub.db`. */
export function getDb(): Db {
	if (!instance) {
		const dir = process.env.DATA_DIR ?? './data';
		mkdirSync(dir, { recursive: true });
		instance = openDb(dbPath(dir));
	}
	return instance;
}

export { schema };
